INSERT INTO dish_steps VALUES(1,1,1,'准备','切肉','五花肉洗净，切成3cm见方的块','5分钟','常温','大小均匀，约麻将牌大小','大小均匀确保受热一致','肉稍微冻硬更好切','切太小会炖碎，切太大不易入味',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(2,1,2,'焯水','冷水下锅','肉块冷水下锅，加姜3片、料酒2汤匙，大火煮开','10分钟','100°C','水面浮起大量灰白色泡沫','冷水缓慢升温，蛋白质凝固析出血沫杂质','冷水下锅，不要热水','热水下锅表面骤然收缩，血沫锁在肉里',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(3,1,3,'焯水','清洗','捞出肉块，用温水冲洗干净浮沫','2分钟','温水','肉块表面干净','洗去表面杂质','用温水，不要冷水','冷水使肉块骤然收缩变硬',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(4,1,4,'炒糖色','融化冰糖','锅中加少许油，放冰糖，小火慢慢融化','3分钟','小火','糖从白色→浅黄→枣红色','蔗糖170°C以上焦糖化反应，产生褐色和焦香','小火慢炒，不停搅动','火太大糖会糊，发苦',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(5,1,5,'煸炒','裹糖色','放入肉块，中火翻炒至每块肉都裹上糖色','3分钟','中火','肉块表面呈枣红色','美拉德反应增香增色','翻炒均匀','火太大糖色会糊',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(6,1,6,'煸炒','逼油','继续煸炒至肉块表面微黄，逼出部分油脂','5分钟','中火','肉块边缘微焦，锅中出油','高温使表面蛋白质变性形成壳，锁住内部水分','耐心煸炒，不要急','煸炒不够成品会腻',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(7,1,7,'调味','加调料','加生抽2汤匙、老抽1汤匙、料酒2汤匙，翻炒均匀','2分钟','中火','肉块均匀上色','酱油氨基酸与糖发生美拉德反应增香增色','先加料酒，再加酱油','酱油加太多会咸',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(8,1,8,'炖煮','加水炖','加热水没过肉，放八角、桂皮、香叶、葱段，大火烧开转小火','60分钟','85-95°C','汤面微微冒泡，不要大滚','85-95°C小火慢炖，胶原蛋白水解成明胶','热水，小火，中途不加冷水','加冷水蛋白质收缩变硬',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(9,1,9,'收汁','大火收汁','挑出香料，大火收汁至汤汁浓稠，不断翻动','5分钟','大火','汤汁浓稠裹在肉上','水分蒸发浓缩风味','不断翻动防粘锅','不翻动会糊底',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(10,1,10,'收尾','出锅','装盘，撒少许葱花点缀','1分钟','-','色泽红亮，汤汁浓稠','-','趁热食用','放凉后脂肪凝固',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
