INSERT INTO dish_steps VALUES(48,7,1,'准备','处理鱼','去鳞去内脏去鳃，清洗干净，特别是鱼腹黑膜','5分钟','-','鱼身干净无黑膜','黑膜是腥味来源','黑膜要去干净','不去黑膜会腥',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
