INSERT INTO dish_steps VALUES(55,7,8,'淋油','泼热油','油烧至冒烟（约200°C），淋在葱姜丝上','1分钟','200°C','滋滋响，激发出香味','高温激发葱姜挥发性香味物质','油要烧热','油不热不出香',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(56,7,9,'调味','淋豉油','沿盘边淋入2汤匙蒸鱼豉油','30秒','-','-','豉油提供鲜味','沿盘边淋，不要直接淋鱼身','淋鱼身会咸',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(57,9,1,'准备','打蛋','鸡蛋打入碗中，加1/4茶匙盐，轻轻打散','1分钟','常温','蛋液均匀，不要打出太多泡沫','打入空气太多蒸后有气泡','轻轻打散，不要用力搅','打太多泡沫蒸后不平',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(58,9,2,'准备','加温水','加入200ml温水（约40°C），搅匀','1分钟','40°C','蛋水混合均匀','温水使蛋液温度均匀，蒸后更嫩','用温水，不要冷水或热水','冷水蒸不匀，热水会烫成蛋花',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(59,9,3,'准备','过滤','用细筛网过滤蛋液，去除泡沫和蛋筋','1分钟','-','蛋液顺滑无泡沫','过滤使蛋液更细腻','一定要过滤','不过滤蒸后有气孔',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(60,9,4,'准备','盖保鲜膜','碗上盖保鲜膜，用牙签戳几个小孔','30秒','-','保鲜膜贴蛋液表面','防止水蒸气滴入形成坑洼','保鲜膜要贴蛋液','不盖会有很多坑',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(61,9,5,'蒸制','蒸','水开后放入，中小火蒸12-15分钟','12-15分钟','中小火','表面凝固，轻晃微微颤动','中小火使蛋白质缓慢凝固，更嫩滑','中小火，不要大火','大火会有蜂窝',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(62,9,6,'收尾','调味','取出，淋生抽、香油，撒葱花','1分钟','-','表面光滑如镜','-','调味后趁热吃','-',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(63,12,1,'准备','划刀','鸡翅两面各划2刀','3分钟','-','刀口均匀','划刀使调味料渗透','划深一点','太浅不入味',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(64,12,2,'焯水','焯水','冷水下锅，加姜片料酒，煮开撇沫，捞出洗净','8分钟','100°C','去血沫','去腥去杂质','冷水下锅','热水会锁住腥味',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(65,12,3,'煎制','煎鸡翅','锅中少油，放鸡翅煎至两面金黄','5分钟','中火','两面金黄','美拉德反应增香','不要急着翻面','翻太勤会破皮',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(66,12,4,'炖煮','加可乐','倒入可乐，加生抽、老抽、葱段，没过鸡翅','25分钟','中小火','汤汁冒泡','可乐糖分焦糖化上色，碳酸嫩肉','可乐要没过鸡翅','可乐不够会干',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(67,12,5,'收汁','收汁','大火收汁至浓稠，不断翻动','5分钟','大火','汤汁浓稠裹在鸡翅上','浓缩风味','不停翻动','不翻会糊',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(68,12,6,'收尾','出锅','装盘，撒白芝麻','1分钟','-','色泽红亮','-','趁热吃','-',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(69,14,1,'准备','打蛋','鸡蛋打散，加少许盐','30秒','-','-','-','-','-',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(70,14,2,'准备','打散米饭','隔夜饭用手或勺子打散，不要有结块','1分钟','-','粒粒分明','打散后炒出来才均匀','提前打散','结块会炒不匀',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(71,14,3,'炒蛋','炒蛋','热锅加油1汤匙，倒入蛋液快速划散，蛋液刚凝固时加入米饭','1分钟','大火','蛋液包裹米饭','蛋液半凝固时加饭，蛋会包裹每粒米','蛋液刚凝固就加饭','蛋炒老了再加饭就晚了',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(72,14,4,'炒饭','翻炒','大火快速翻炒，让蛋液均匀包裹米饭','3分钟','大火','米粒金黄，粒粒分明','大火使水分快速蒸发，米粒分明','大火，快速翻炒','火小会粘锅',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(73,14,5,'调味','调味','加盐1/2茶匙，翻炒均匀','30秒','大火','-','-','盐少放','盐太多会咸',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(74,14,6,'收尾','加葱花','撒葱花，翻炒几下出锅','30秒','大火','有葱香味','葱花最后放保留香味','葱花不要太早放','太早放葱会黄',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(75,15,1,'准备','备料','所有配料切丁，虾仁去虾线','10分钟','-','大小均匀约1cm','大小均匀受热一致','提前备好','边炒边切会手忙脚乱',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
