INSERT INTO dish_steps VALUES(78,15,4,'炒蛋','炒蛋','加油，倒入蛋液，快速划散','30秒','大火','蛋液刚凝固','-','-','-',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
INSERT INTO dish_steps VALUES(79,15,5,'炒饭','加饭炒','加入米饭，大火快速翻炒3分钟','3分钟','大火','米粒分明','大火蒸发水分','大火快炒','火小会粘',NULL,'wikiHow / 中国烹饪协会','wikiHow cooking guides + 中国烹饪协会','https://www.wikihow.com/ | http://www.ccas.com.cn/','curated/compiled');
